CREATE TABLE IF NOT EXISTS foremen(id TEXT PRIMARY KEY, terminal_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,foreman TEXT NOT NULL,role TEXT NOT NULL,checkout TEXT NOT NULL,state TEXT NOT NULL,request TEXT NOT NULL,session_id TEXT NOT NULL UNIQUE,prompt_id TEXT NOT NULL UNIQUE,sparse INTEGER NOT NULL,result TEXT NOT NULL DEFAULT '',detail TEXT NOT NULL DEFAULT '',created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,task_id TEXT NOT NULL UNIQUE,foreman TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',request_id TEXT NOT NULL UNIQUE,acked INTEGER NOT NULL DEFAULT 0,next_receipt REAL NOT NULL DEFAULT 0,transport TEXT NOT NULL DEFAULT 'native',detail TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS approvals(task_id TEXT NOT NULL,permission_id TEXT NOT NULL,foreman TEXT NOT NULL,form_id TEXT NOT NULL UNIQUE,snapshot TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',PRIMARY KEY(task_id,permission_id));
CREATE TABLE IF NOT EXISTS plans(foreman TEXT PRIMARY KEY,items TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS progress_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,foreman TEXT NOT NULL,fingerprint TEXT NOT NULL,snapshot TEXT NOT NULL,request_id TEXT NOT NULL UNIQUE,state TEXT NOT NULL DEFAULT 'pending',sent_at REAL NOT NULL DEFAULT 0,next_receipt REAL NOT NULL DEFAULT 0,detail TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS workflows(id TEXT PRIMARY KEY,foreman TEXT NOT NULL,project TEXT NOT NULL,request TEXT NOT NULL,policy TEXT NOT NULL,base_revision TEXT,state TEXT NOT NULL DEFAULT 'queued',round INTEGER NOT NULL DEFAULT 0,data TEXT NOT NULL DEFAULT '{"rounds":[]}',detail TEXT NOT NULL DEFAULT '',created REAL NOT NULL);
CREATE TABLE IF NOT EXISTS managed_checkouts(path TEXT PRIMARY KEY,workflow_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_todos(task_id TEXT PRIMARY KEY,todos TEXT,message_id TEXT,next_read REAL NOT NULL DEFAULT 0,final INTEGER NOT NULL DEFAULT 0,detail TEXT NOT NULL DEFAULT '');
